from collections import Counter

def maxDifference(s: str) -> int:
    frequency = Counter(s)
    max_odd = -1
    max_even = -1

    for count in frequency.values():
        if count % 2 == 0:
            max_even = max(max_even, count)
        else:
            max_odd = max(max_odd, count)

    return max_odd - max_even

