def maximumCoins(coins: List[List[int]], k: int) -> int:
    # Create a list to represent the coin counts at each position
    max_position = 0
    for l, r, c in coins:
        max_position = max(max_position, r)

    bags = [0] * (max_position + 1)

    # Fill the bags with coin counts based on the input
    for l, r, c in coins:
        for i in range(l, r + 1):
            bags[i] += c

    # Initialize the sliding window for the maximum coins
    current_coins = 0
    max_coins = 0
    for i in range(1, len(bags)):
        current_coins += bags[i]
        if i >= k:
            max_coins = max(max_coins, current_coins)
            current_coins -= bags[i - k + 1]

    return max_coins

