def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[float('-inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Start at (0, 0) with initial coins

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k is the number of robbers neutralized
                if i == 0 and j == 0:
                    continue  # Skip starting cell
                # Move from the top
                if i > 0:
                    gain = coins[i][j]
                    if gain < 0:
                        if k > 0:  # Neutralize robber
                            dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1])
                        else:
                            dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + gain)
                    else:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + gain)
                # Move from the left
                if j > 0:
                    gain = coins[i][j]
                    if gain < 0:
                        if k > 0:  # Neutralize robber
                            dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1])
                        else:
                            dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + gain)
                    else:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + gain)

    return max(dp[m-1][n-1])

