def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Sort edges by weight
    edges.sort(key=lambda x: x[2])

    def canReachNodeZero(max_weight: int) -> bool:
        from collections import defaultdict, deque
        graph = defaultdict(list)
        out_degrees = [0] * n

        for u, v, w in edges:
            if w <= max_weight and out_degrees[u] < threshold:
                graph[v].append(u)  # reverse the graph
                out_degrees[u] += 1

        # BFS or DFS to check if all nodes can reach node 0
        reachable = [False] * n
        queue = deque([0])
        reachable[0] = True

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not reachable[neighbor]:
                    reachable[neighbor] = True
                    queue.append(neighbor)

        return all(reachable)

    left, right = 1, 10**6
    answer = -1

    while left <= right:
        mid = (left + right) // 2
        if canReachNodeZero(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    return answer

