def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]

    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(
                dp[i - 1][(j + 1) % 3],  # previous house, different color
                dp[i - 1][(j + 2) % 3]   # previous house, different color
            )

    # Handle the mirrored houses by utilizing previous results
    for i in range(n // 2):
        for j in range(3):
            dp[i + n // 2][j] = float('inf')
            if j != (i + n // 2) % 3:
                dp[i + n // 2][j] = min(dp[i + n // 2][j], 
                                          cost[i + n // 2][j] + 
                                          min(dp[i][(j + 1) % 3], 
                                              dp[i][(j + 2) % 3]))

    return min(dp[n - 1])

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in sorted(events, key=lambda x: int(x[1])):
        event_type, timestamp, *payload = event
        timestamp = int(timestamp)

        # Process offline users before handling the event
        for i in range(numberOfUsers):
            if not online_status[i] and timestamp >= offline_until[i]:
                online_status[i] = True

        if event_type == 'OFFLINE':
            user_id = int(payload[0])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60
        elif event_type == 'MESSAGE':
            mentions_string = payload[0]
            if mentions_string == 'ALL':
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == 'HERE':
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    user_id = int(mention[2:])
                    mentions[user_id] += 1

    return mentions

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0

    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1

        # Current Manhattan distance from the origin
        current_distance = abs(x) + abs(y)
        max_distance = max(max_distance, current_distance)

    # Maximum distance can be increased by k (changing directions)
    total_distance = max_distance + k
    return total_distance
